  "footer.dataset": { en: "Data: AED_EARNINGS_COMPLETE.DTA (872 full-time workers aged 25–65, 2000)", es: "Datos: AED_EARNINGS_COMPLETE.DTA (872 trabajadores a tiempo completo de 25 a 65 años, 2000)" },
  "footer.scrolltop": { en: "↑ Back to top", es: "↑ Volver arriba" },
  "footer.text": { en: "Part of <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Chapter 15: Regression with Transformed Variables · by Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", es: "Parte de <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Capítulo 15: Regresión con variables transformadas · por Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>" },
